<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';require dirname(__DIR__,2).'/vendor/yiisoft/yii2/Yii.php';
use FMonitor2\YiiRuntime\{ReadOnlySession,ReliableSession};
// PRODUCTION-PERFORMANCE-001 A04 uses a real PHP file lock, not a mocked session.
final class PerformanceIdentity implements yii\web\IdentityInterface{public static function findIdentity($id){return new self();}public static function findIdentityByAccessToken($token,$type=null){return null;}public function getId(){return 91;}public function getAuthKey(){return'test';}public function validateAuthKey($key){return$key==='test';}}
$dir=sys_get_temp_dir().'/fm2-perf-session-'.bin2hex(random_bytes(5));mkdir($dir,0700);$_SERVER['REQUEST_METHOD']='GET';$_SERVER['SCRIPT_FILENAME']=__FILE__;$_SERVER['SCRIPT_NAME']='/index.php';$_SERVER['REQUEST_URI']='/pure-read';$_SERVER['HTTP_HOST']='fmonitor.example.test';
$app=new yii\web\Application(['id'=>'perf-test','basePath'=>dirname(__DIR__,2),'components'=>['request'=>['cookieValidationKey'=>'test-secret','enableCsrfCookie'=>false],'session'=>['class'=>ReliableSession::class,'savePath'=>$dir,'useCookies'=>false,'name'=>'perfTest'],'user'=>['identityClass'=>PerformanceIdentity::class,'enableSession'=>true]]]);
try{$app->session->open();$app->user->setIdentity(new PerformanceIdentity());$app->session->set('marker','persistent');$token=$app->request->csrfToken;$id=$app->session->id;$lock=fopen($dir.'/sess_'.$id,'r+');assertSameValue(false,flock($lock,LOCK_EX|LOCK_NB),'fixture holds actual exclusive native session lock');
ReadOnlySession::release();assertSameValue(false,$app->session->isActive,'A04 no active lock after read handoff');assertSameValue(true,flock($lock,LOCK_EX|LOCK_NB),'another file descriptor can acquire session immediately');flock($lock,LOCK_UN);fclose($lock);
assertSameValue($token,$app->request->csrfToken,'render token unchanged');assertSameValue(91,$app->user->id,'render actor unchanged');assertSameValue(false,$app->session->isActive,'render access does not reopen session');
$app->session->open();assertSameValue('persistent',$app->session->get('marker'),'committed session data survives');$_SERVER['REQUEST_METHOD']='POST';assertSameValue(true,$app->request->validateCsrfToken($token),'captured token valid after reopen');assertSameValue(false,$app->request->validateCsrfToken('invalid'),'invalid CSRF remains rejected');$failed=false;try{ReadOnlySession::release();}catch(LogicException){$failed=true;}assertSameValue(true,$failed,'session writers cannot use readonly handoff');assertSameValue(true,$app->session->isActive,'rejected write handoff keeps writer session');$app->session->close();echo "PASS PRODUCTION-PERFORMANCE-001 A04 native session lock\n";
}finally{if($app->session->isActive)$app->session->close();foreach(glob($dir.'/*')?:[]as$f)unlink($f);rmdir($dir);}
